Age beats depth: depth is a number, age is an SLA.

values.yaml

image:
  repository: <acct>.dkr.ecr.../dgcl
  tag: ""                 # set to git sha at deploy

services:
  api:        {replicas: 2,  port: 8000}
  ingestion:  {replicas: 1}
  idp:        {keda: {min: 2, max: 20, queue: q.idp}}
  reasoning:  {keda: {min: 2, max: 40, queue: q.reason}}
  assembly:   {replicas: 2}

gpu: {enabled: true, nodeSelector: {workload: gpu}}
external: {postgresHost, redisHost, s3Bucket}
